class Team(BaseModel):
    """Data representing a Team."""

    model_config = ConfigDict(populate_by_name=True, arbitrary_types_allowed=True, extra="allow")

    avatar: str | None
    """
    The ID of the file used as avatar for this Team.

    @example "6eb07268bcfadd309905ffb1579354084c24655c"
    """
    billing: TeamBilling | None
    """The team's billing plan."""
    created_at: float = Field(alias="createdAt")
    """
    UNIX timestamp (in milliseconds) when the Team was created.

    @example 1630748523395
    """
    creator_id: str = Field(alias="creatorId")
    """
    The ID of the user who created the Team.

    @example "R6efeCJQ2HKXywuasPDc0fOWB"
    """
    description: str | None
    """
    A short description of the Team.

    @example "Our mission is to make cloud computing accessible to everyone."
    """
    id: str
    """
    The Team's unique identifier.

    @example "team_nllPyCtREAqxxdyFKbbMDlxd"
    """
    limited: bool
    """Property indicating that this Team data contains full information. Limited Team data has `limited: true`."""
    name: str | None
    """
    Name associated with the Team account, or `null` if none has been provided.

    @example "My Team"
    """
    slug: str
    """
    The Team's slug, which is unique across the Vercel platform.

    @example "my-team"
    """
    staging_prefix: str = Field(alias="stagingPrefix")
    """The prefix that is prepended to automatic aliases."""
    updated_at: float = Field(alias="updatedAt")
    """
    Timestamp (in milliseconds) of when the Team was last updated.

    @example 1611796915677
    """
    api_keys_invalidated_at: float | NotGiven = Field(NOT_GIVEN, alias="apiKeysInvalidatedAt")
    """Timestamp (ms) after which API keys created at or before this time are considered invalid for this team."""
    app_tokens_invalidated_at: float | NotGiven = Field(NOT_GIVEN, alias="appTokensInvalidatedAt")
    """Timestamp (ms) after which Vercel App tokens created at or before this time are considered invalid for this team."""
    connect: TeamConnect | NotGiven = NOT_GIVEN
    """Optional object value serialized in the `connect` wire field."""
    default_continuous_usage_kind: Literal["metered", "unmetered"] | str | NotGiven = Field(
        NOT_GIVEN, alias="defaultContinuousUsageKind"
    )
    """Default continuous-usage billing kind for projects under this team. Absent means projects stay unmetered."""
    default_deployment_protection: TeamDefaultDeploymentProtection | NotGiven = Field(
        NOT_GIVEN, alias="defaultDeploymentProtection"
    )
    """Default deployment protection for this team null indicates protection is disabled"""
    default_expiration_settings: TeamDefaultExpirationSettings | NotGiven = Field(
        NOT_GIVEN, alias="defaultExpirationSettings"
    )
    """Default deployment expiration settings for this team"""
    default_passport: TeamDefaultPassport | None | NotGiven = Field(
        NOT_GIVEN, alias="defaultPassport"
    )
    """Default Passport configuration for new projects in this team."""
    default_project_jobs: TeamDefaultProjectJobs | NotGiven = Field(
        NOT_GIVEN, alias="defaultProjectJobs"
    )
    """Default job configuration applied to new projects created in this team."""
    default_roles: TeamDefaultRoles | NotGiven = Field(NOT_GIVEN, alias="defaultRoles")
    """Default roles for the team."""
    deployment_policy: TeamDeploymentPolicy | NotGiven = Field(NOT_GIVEN, alias="deploymentPolicy")
    """Composable deployment-time policy for the team. Used as the default for every project on the team, with optional per-project overrides on `project.deploymentPolicy`."""
    deployment_storage_rollout: TeamDeploymentStorageRollout | NotGiven = Field(
        NOT_GIVEN, alias="deploymentStorageRollout"
    )
    """Pro deployment-storage pricing rollout cohort and milestones. Absent when the team has not been placed in a rollout cohort yet."""
    disable_hard_auto_blocks: float | bool | NotGiven = Field(
        NOT_GIVEN, alias="disableHardAutoBlocks"
    )
    """Optional API value serialized in the `disableHardAutoBlocks` wire field."""
